/* What rangeify makes of reduce op=add: start from x[0], add x[1..n-1] in order. n >= 1. */
float sum_left(const float *x, int n) {
  float acc = 0.0f;
  for (int i = 0; i < n; i++) acc = acc + x[i];
  return acc;
}

answer.code:
float sum_left(const float *x, int n) {
  float acc = x[0];
  for (int i = 1; i < n; i++) acc = acc + x[i];
  return acc;
}
